(2917260, 409661, 43774, '<td valign="top">Aww, cute pose. I like the idea and the setup but the lighting could use a bit of work and perhaps the DOF could be larger.</td>', 'Aww, cute pose. I like the idea and the setup but the lighting could use a bit of work and perhaps the DOF could be larger.', '2006-10-11 09:09:11.000000', NULL, 1),
(2917262, 409562, 43774, '<td valign="top">I love the setup and the lighting/tones. The afro I don''t get. It looks like something added in photoshop</td>', 'I love the setup and the lighting/tones. The afro I don''t get. It looks like something added in photoshop', '2006-10-11 09:10:15.000000', NULL, 1),
