(2919669, 409761, 66515, '<td valign="top">Excellent composition on superb depth of field really makes this picture pop. I really like the detail in this photograph.</td>', 'Excellent composition on superb depth of field really makes this picture pop. I really like the detail in this photograph.', '2006-10-11 18:11:06.000000', NULL, 1),
(2919671, 408764, 66515, '<td valign="top">Very clever and unique idea. The "ropes" and shroud really make this picture. Outstanding!</td>', 'Very clever and unique idea. The "ropes" and shroud really make this picture. Outstanding!', '2006-10-11 18:12:22.000000', NULL, 1),
(2919676, 409505, 66515, '<td valign="top">Very clever setup. I really like the colours and the pose you''ve selected.</td>', 'Very clever setup. I really like the colours and the pose you''ve selected.', '2006-10-11 18:14:21.000000', NULL, 1),
