(2920551, 408823, 43774, '<td valign="top">I like the composition and the stars in the background but I am not fond of the orange light on Woody.</td>', 'I like the composition and the stars in the background but I am not fond of the orange light on Woody.', '2006-10-11 22:18:42.000000', NULL, 1),
(2920554, 407522, 43774, '<td valign="top">Cute setup up, I''d like to see more DOF.</td>', 'Cute setup up, I''d like to see more DOF.', '2006-10-11 22:18:57.000000', NULL, 1),
(2920620, 409084, 30982, '<td valign="top">Kinda like the dish ran away with the spoon, only not.  Nice setup and good poses.</td>', 'Kinda like the dish ran away with the spoon, only not.  Nice setup and good poses.', '2006-10-11 22:42:08.000000', NULL, 1),
(2920621, 409237, 30982, '<td valign="top">Very well done even though he''s plastic - great detail, nice background.  Points for stepping outta the box a little, too.</td>', 'Very well done even though he''s plastic - great detail, nice background.  Points for stepping outta the box a little, too.', '2006-10-11 22:42:47.000000', NULL, 1),
(2920624, 409829, 30982, '<td valign="top">Aww - the Woody family in their natural environment!</td>', 'Aww - the Woody family in their natural environment!', '2006-10-11 22:43:19.000000', NULL, 1),
(2920626, 407528, 30982, '<td valign="top">How sweet of him!</td>', 'How sweet of him!', '2006-10-11 22:43:48.000000', NULL, 1),
(2920629, 408764, 30982, '<td valign="top">Ummm... that''s really.. umm... OW!  Very nicely set up and shot - great light, nice DOF.</td>', 'Ummm... that''s really.. umm... OW!  Very nicely set up and shot - great light, nice DOF.', '2006-10-11 22:44:22.000000', NULL, 1),
