(2920632, 409562, 25355, '<td valign="top">I''m not sure that the background serves well for this photo; and it looks as if you have his head facing the wrong way. ;-)</td>', 'I''m not sure that the background serves well for this photo; and it looks as if you have his head facing the wrong way. ;-)', '2006-10-11 22:44:53.000000', NULL, 1),
