(2920641, 409751, 30982, '<td valign="top">The title is priceless; wordy, but priceless.  Very creative!</td>', 'The title is priceless; wordy, but priceless.  Very creative!', '2006-10-11 22:48:13.000000', NULL, 1),
(2920643, 408456, 30982, '<td valign="top">Add a board and it could be surfer woody - kinda looks like the crest of a wave.</td>', 'Add a board and it could be surfer woody - kinda looks like the crest of a wave.', '2006-10-11 22:48:45.000000', NULL, 1),
(2920646, 406237, 30982, '<td valign="top">The challenge description was: Include a Woody in your photograph this week. Note: A woody is a wooden stick man seen here. Use the photo search to see more examples of woodies.  Usually there''s a more complete description other than the one world title for each of the challenges.  Also, under the Learn section, there''s a tutorial on how to size pictures for submission - if you use the maximum allowed size, people will be able to see your pictures more clearly.</td>', 'The challenge description was: Include a Woody in your photograph this week. Note: A woody is a wooden stick man seen here. Use the photo search to see more examples of woodies.  Usually there''s a more complete description other than the one world title for each of the challenges.  Also, under the Learn section, there''s a tutorial on how to size pictures for submission - if you use the maximum allowed size, people will be able to see your pictures more clearly.', '2006-10-11 22:50:30.000000', NULL, 1),
(2920648, 409253, 30982, '<td valign="top">Nice pose, nice light!</td>', 'Nice pose, nice light!', '2006-10-11 22:51:00.000000', NULL, 1),
(2920649, 409796, 30982, '<td valign="top">Oh dear.  Hopefully Woody can things back on track.  Nice idea and good execution.</td>', 'Oh dear.  Hopefully Woody can things back on track.  Nice idea and good execution.', '2006-10-11 22:51:28.000000', NULL, 1),
