INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2923117, 408865, 65083, '<td valign="top">this made me laugh :)</td>', 'this made me laugh :)', '2006-10-12 16:36:47.000000', NULL, 1),
(2923119, 408773, 64446, '<td valign="top">I don''t like and DNMC.</td>', 'I don''t like and DNMC.', '2006-10-12 16:37:02.000000', NULL, 1),
(2923120, 409811, 65083, '<td valign="top">great picture</td>', 'great picture', '2006-10-12 16:37:21.000000', NULL, 1),
(2923125, 409816, 65083, '<td valign="top">great idea</td>', 'great idea', '2006-10-12 16:38:29.000000', NULL, 1),
(2923127, 409811, 30049, '<td valign="top">Clever use of mirrors like that.  I like the leading line effect and the creative wall and "ground" you''ve put together.  Seems a little grainy, but not terrible.  Good use of a full 640 x 640.  Good luck in the challenge.</td>', 'Clever use of mirrors like that.  I like the leading line effect and the creative wall and "ground" you''ve put together.  Seems a little grainy, but not terrible.  Good use of a full 640 x 640.  Good luck in the challenge.', '2006-10-12 16:39:14.000000', NULL, 1),
(2923130, 408764, 65083, '<td valign="top">geat pictures cool thought</td>', 'geat pictures cool thought', '2006-10-12 16:39:42.000000', NULL, 1),
(2923134, 409702, 30049, '<td valign="top">This is clever.  Not sure how you could have gotten the TV screen to be clearer.  Pretty sure you needed a slower shutter speed to avoid getting the horizontal bars - with an action scene on the screen you then get blurry output.  Perhaps if you had used a movie and paused it?  Just a thought.  Good luck in the challenge.</td>', 'This is clever.  Not sure how you could have gotten the TV screen to be clearer.  Pretty sure you needed a slower shutter speed to avoid getting the horizontal bars - with an action scene on the screen you then get blurry output.  Perhaps if you had used a movie and paused it?  Just a thought.  Good luck in the challenge.', '2006-10-12 16:41:35.000000', NULL, 1),
(2923148, 409759, 65083, '<td valign="top">took me a second to get it great photo</td>', 'took me a second to get it great photo', '2006-10-12 16:44:39.000000', NULL, 1),
(2923156, 407490, 30049, '<td valign="top">This almost looks like it was shot with a glass front or something.  The photo isn''t quite clear.  Little soft (not well focused) and could use a boost of contrast to give it more depth/clarity.  Use of a tripod would eliminate the camera shake (with camera timer used).  Subject matter, well, that''s personal preference - I''m familiar with a couple of those book titles but religious themes don''t always go over too well with voters at DPC.  Nothing wrong in spreading the Word, but be prepared for some potential backlash.  The primary subject for this challenge is Woody.  In your shot Woody is nearly a secondary subject.   JMO of course.  Best of luck to you in the challenge.</td>', 'This almost looks like it was shot with a glass front or something.  The photo isn''t quite clear.  Little soft (not well focused) and could use a boost of contrast to give it more depth/clarity.  Use of a tripod would eliminate the camera shake (with camera timer used).  Subject matter, well, that''s personal preference - I''m familiar with a couple of those book titles but religious themes don''t always go over too well with voters at DPC.  Nothing wrong in spreading the Word, but be prepared for some potential backlash.  The primary subject for this challenge is Woody.  In your shot Woody is nearly a secondary subject.   JMO of course.  Best of luck to you in the challenge.', '2006-10-12 16:48:30.000000', NULL, 1),
(2923170, 409593, 58610, '<td valign="top">Go, Woddy, Go!(Have you had enough of that, yet?)</td>', 'Go, Woddy, Go!(Have you had enough of that, yet?)', '2006-10-12 16:51:00.000000', NULL, 1),
(2923175, 408762, 58610, '<td valign="top">There''s a story in here, somewhere.</td>', 'There''s a story in here, somewhere.', '2006-10-12 16:52:09.000000', NULL, 1),
(2923189, 406150, 58610, '<td valign="top">I bet you just walked into the art store and took this, didn''t you?</td>', 'I bet you just walked into the art store and took this, didn''t you?', '2006-10-12 16:55:06.000000', NULL, 1),
(2923201, 409738, 58610, '<td valign="top">Woodyfylingly Ducklishious</td>', 'Woodyfylingly Ducklishious', '2006-10-12 16:58:05.000000', NULL, 1),
(2923203, 409593, 24715, '<td valign="top">Excellent photo! Superb lighting and setup.</td>', 'Excellent photo! Superb lighting and setup.', '2006-10-12 16:58:36.000000', NULL, 1),
(2923209, 409761, 24715, '<td valign="top">One of my favorites in the challenge. Unique setup and excellent execution.</td>', 'One of my favorites in the challenge. Unique setup and excellent execution.', '2006-10-12 17:00:15.000000', NULL, 1),
(2923210, 409816, 24715, '<td valign="top">Wow! Nice detail, excellent lighting. B&amp;W really works here.</td>', 'Wow! Nice detail, excellent lighting. B&W really works here.', '2006-10-12 17:01:00.000000', NULL, 1),
(2923213, 409453, 24715, '<td valign="top">Nice perspective and object placement. Lighting is also very good. Great job!</td>', 'Nice perspective and object placement. Lighting is also very good. Great job!', '2006-10-12 17:02:09.000000', NULL, 1),
(2923220, 409759, 24715, '<td valign="top">Excellent photo and the idea is a hoot! Lighting and focus are excellent!</td>', 'Excellent photo and the idea is a hoot! Lighting and focus are excellent!', '2006-10-12 17:03:47.000000', NULL, 1),
(2923255, 409703, 52449, '<td valign="top">Lighting is a bit harsh. Maybe later or earlier in the day would have helped.</td>', 'Lighting is a bit harsh. Maybe later or earlier in the day would have helped.', '2006-10-12 17:23:21.000000', NULL, 1),
(2923268, 409515, 52449, '<td valign="top">There are some blown-out areas where the lighting was too harsh on the face and chest areas. Softer lighting would have earned a higher vote.</td>', 'There are some blown-out areas where the lighting was too harsh on the face and chest areas. Softer lighting would have earned a higher vote.', '2006-10-12 17:30:59.000000', NULL, 1),
(2923277, 406237, 52449, '<td valign="top">The photo is so small, I am unable to see Woody.</td>', 'The photo is so small, I am unable to see Woody.', '2006-10-12 17:36:38.000000', NULL, 1),
