(2923329, 409377, 52449, '<td valign="top">Where''s Woody?</td>', 'Where''s Woody?', '2006-10-12 18:03:06.000000', NULL, 1),
(2923379, 408173, 30982, '<td valign="top">Wow - excellent idea, very well executed.  Love the dreary, gritty, sad feel - focus is just right where it should be.  Great lighting.  Back to bump - you''re one of my top two - good luck!</td>', 'Wow - excellent idea, very well executed.  Love the dreary, gritty, sad feel - focus is just right where it should be.  Great lighting.  Back to bump - you''re one of my top two - good luck!', '2006-10-12 18:25:53.000000', NULL, 1),
(2923380, 409827, 30982, '<td valign="top">Great concept!  Nicely toned.</td>', 'Great concept!  Nicely toned.', '2006-10-12 18:25:57.000000', NULL, 1),
(2923381, 409702, 30982, '<td valign="top">Ah, movie night at the Woody household.  Nice blurred image from the screen.</td>', 'Ah, movie night at the Woody household.  Nice blurred image from the screen.', '2006-10-12 18:26:00.000000', NULL, 1),
(2923383, 409657, 30982, '<td valign="top">Very nice study in light and soft tones!</td>', 'Very nice study in light and soft tones!', '2006-10-12 18:26:04.000000', NULL, 1),
(2923385, 408126, 30982, '<td valign="top">Lovely emotive shot.  Nice use of light and negative space!</td>', 'Lovely emotive shot.  Nice use of light and negative space!', '2006-10-12 18:26:30.000000', NULL, 1),
(2923386, 409730, 30982, '<td valign="top">Either that''s a pretty good sized Woody (I can''t believe I just typed that) or it''s a very small ducky.  Nice light, nice warm tones, good detail.</td>', 'Either that''s a pretty good sized Woody (I can''t believe I just typed that) or it''s a very small ducky.  Nice light, nice warm tones, good detail.', '2006-10-12 18:26:42.000000', NULL, 1),
(2923387, 407358, 63588, '<td valign="top">DNMC - Don''t see a Woody.</td>', 'DNMC - Don''t see a Woody.', '2006-10-12 18:26:44.000000', NULL, 1),
(2923388, 406444, 30982, '<td valign="top">Oooh - I like the outlined silhouette!  Nice tones, too.</td>', 'Oooh - I like the outlined silhouette!  Nice tones, too.', '2006-10-12 18:26:46.000000', NULL, 1),
(2923391, 407490, 63588, '<td valign="top">Woodies don''t appear to be in focus.</td>', 'Woodies don''t appear to be in focus.', '2006-10-12 18:27:19.000000', NULL, 1),
(2923392, 408462, 30982, '<td valign="top">Very nice composition and lovely colors!</td>', 'Very nice composition and lovely colors!', '2006-10-12 18:27:20.000000', NULL, 1),
(2923397, 406884, 63588, '<td valign="top">the pole holding up the Woody is what gets my eye''s attention. The OOF leg distracts my eye. I like the b&amp;w white conversion.</td>', 'the pole holding up the Woody is what gets my eye''s attention. The OOF leg distracts my eye. I like the b&w white conversion.', '2006-10-12 18:28:48.000000', NULL, 1),
(2923399, 409379, 63588, '<td valign="top">DNMC (at least I don''t see a Woody - a larger size image would help). Like the composition.</td>', 'DNMC (at least I don''t see a Woody - a larger size image would help). Like the composition.', '2006-10-12 18:29:49.000000', NULL, 1),
