(2927596, 409738, 24846, '<td valign="top">lol great !</td>', 'lol great !', '2006-10-14 01:48:35.000000', NULL, 1),
(2927598, 409562, 24846, '<td valign="top">LOL ?microphone cover</td>', 'LOL ?microphone cover', '2006-10-14 01:51:01.000000', NULL, 1),
(2927600, 409266, 56454, '<td valign="top">Exceptional lighting of Woody.  It really gives definition to his "face".  The angle of the shot and compostion are well done also.  Something about the noose doesn''t look quite right to me but I can''t put my finger on it. Maybe too white?  Regardless, it''s a very good photo.</td>', 'Exceptional lighting of Woody.  It really gives definition to his "face".  The angle of the shot and compostion are well done also.  Something about the noose doesn''t look quite right to me but I can''t put my finger on it. Maybe too white?  Regardless, it''s a very good photo.', '2006-10-14 01:51:48.000000', NULL, 1),
(2927607, 407406, 56454, '<td valign="top">Very clever idea.  I really like the lighting and effect of being wet on Woody.  The lighting at the top of the picture is distracting to me though.  I would consider cropping just above or just below the debris in the water.  I like the crop without the feet. It gives a sense that is actually drifting away.</td>', 'Very clever idea.  I really like the lighting and effect of being wet on Woody.  The lighting at the top of the picture is distracting to me though.  I would consider cropping just above or just below the debris in the water.  I like the crop without the feet. It gives a sense that is actually drifting away.', '2006-10-14 01:57:16.000000', NULL, 1),
(2927608, 409827, 56454, '<td valign="top">I love the lighting (color and direction).  Composition is strong too.  I even like the use of that ribbon-type thing with the images on it.  ;-)</td>', 'I love the lighting (color and direction).  Composition is strong too.  I even like the use of that ribbon-type thing with the images on it.  ;-)', '2006-10-14 01:59:49.000000', NULL, 1),
(2927613, 409495, 56454, '<td valign="top">I like the idea of contrasting the plain Woody against the color of the flowers.  However, the lighting (looks like a flash) really flattens the image and washes out textures.</td>', 'I like the idea of contrasting the plain Woody against the color of the flowers.  However, the lighting (looks like a flash) really flattens the image and washes out textures.', '2006-10-14 02:09:38.000000', NULL, 1),
(2927614, 409254, 56454, '<td valign="top">Took me a minute to figure out the mixed "fairy tale" references.  Unfortunately, Woody is out of focus.  The reflections in the table are a little distracting as well.</td>', 'Took me a minute to figure out the mixed "fairy tale" references.  Unfortunately, Woody is out of focus.  The reflections in the table are a little distracting as well.', '2006-10-14 02:12:46.000000', NULL, 1),
(2927618, 409582, 56454, '<td valign="top">Clever idea.  Background elements, while out of focus, are still distracting.</td>', 'Clever idea.  Background elements, while out of focus, are still distracting.', '2006-10-14 02:17:38.000000', NULL, 1),
(2927621, 408456, 56454, '<td valign="top">Nice idea and good composition.  Woody appears to be out of focus and the light trails may look better if they were straight.</td>', 'Nice idea and good composition.  Woody appears to be out of focus and the light trails may look better if they were straight.', '2006-10-14 02:22:06.000000', NULL, 1),
(2927626, 407490, 56454, '<td valign="top">Interesting collection for Woody.  I would have thought he would be more into carpentry or woodworking.  Unfortunately, focus seems to be a problem.</td>', 'Interesting collection for Woody.  I would have thought he would be more into carpentry or woodworking.  Unfortunately, focus seems to be a problem.', '2006-10-14 02:25:40.000000', NULL, 1),
(2927628, 408353, 55621, '<td valign="top">DNMC</td>', 'DNMC', '2006-10-14 02:27:34.000000', NULL, 1),
(2927629, 408254, 56454, '<td valign="top">Composition is good.  The image is small which makes it harder to see details and makes it less powerful.  Lighting is a little harsh too.</td>', 'Composition is good.  The image is small which makes it harder to see details and makes it less powerful.  Lighting is a little harsh too.', '2006-10-14 02:28:26.000000', NULL, 1),
(2927631, 407522, 55621, '<td valign="top">This is a good concept, better use of DOF would have helped with focus</td>', 'This is a good concept, better use of DOF would have helped with focus', '2006-10-14 02:30:03.000000', NULL, 1),
(2927632, 406884, 56454, '<td valign="top">I like the unique perspective.  I think that a darker background would make Woody stand out.  While I don''t mind not seeing his feet, his missing hand makes me wonder why it''s off frame.</td>', 'I like the unique perspective.  I think that a darker background would make Woody stand out.  While I don''t mind not seeing his feet, his missing hand makes me wonder why it''s off frame.', '2006-10-14 02:30:23.000000', NULL, 1),
(2927641, 409477, 56454, '<td valign="top">What a unique Woody.  Unlike most of the other Woody''s, a think an even lighter background may have been better.  Also, more distance between Woody and the background would eliminate the shadow.  Maybe it needs to be leaned to stay standing.  I can''t help but wondering what a classic, head-and-shoulders portrait of this woody would look like.</td>', 'What a unique Woody.  Unlike most of the other Woody''s, a think an even lighter background may have been better.  Also, more distance between Woody and the background would eliminate the shadow.  Maybe it needs to be leaned to stay standing.  I can''t help but wondering what a classic, head-and-shoulders portrait of this woody would look like.', '2006-10-14 02:36:44.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2927644, 409702, 55621, '<td valign="top">Reminds me of MST2K, all you needed was Mike Nelson.</td>', 'Reminds me of MST2K, all you needed was Mike Nelson.', '2006-10-14 02:38:05.000000', NULL, 1),
(2927651, 409562, 56454, '<td valign="top">I love the hair, the pose, and the lighting.  I don''t understand how it fits into the "rustic" setting with a wood bench and leaves, though.</td>', 'I love the hair, the pose, and the lighting.  I don''t understand how it fits into the "rustic" setting with a wood bench and leaves, though.', '2006-10-14 02:42:20.000000', NULL, 1),
(2927655, 409772, 56454, '<td valign="top">Very clever idea.  I like the composition and props.  Lighting is a little flat and the exposure seems "muddy".  Some more directional light and contrast may make it more dramatic.</td>', 'Very clever idea.  I like the composition and props.  Lighting is a little flat and the exposure seems "muddy".  Some more directional light and contrast may make it more dramatic.', '2006-10-14 02:45:34.000000', NULL, 1),
(2927660, 407677, 56454, '<td valign="top">Unique idea and nice use of perspective.  Lighting and composition are good too.</td>', 'Unique idea and nice use of perspective.  Lighting and composition are good too.', '2006-10-14 02:50:50.000000', NULL, 1),
(2927687, 408764, 48545, '<td valign="top">great image, great light, novel idea</td>', 'great image, great light, novel idea', '2006-10-14 03:46:12.000000', NULL, 1),
(2927688, 409611, 48545, '<td valign="top">Great poses, good light, can''t think of anyway this can be improved</td>', 'Great poses, good light, can''t think of anyway this can be improved', '2006-10-14 03:46:20.000000', NULL, 1),
(2927689, 408173, 48545, '<td valign="top">I love this. Great interest, like the ''slight'' softness - I believe this was all intentional.  The border mmmmmm think it also works as it feels like you are looking in on a situtation.</td>', 'I love this. Great interest, like the ''slight'' softness - I believe this was all intentional.  The border mmmmmm think it also works as it feels like you are looking in on a situtation.', '2006-10-14 03:46:28.000000', NULL, 1),
(2927690, 409775, 48545, '<td valign="top">great that there is actually atmosphere in this image of lumps of wood. The focus is a little soft on his hands and knees</td>', 'great that there is actually atmosphere in this image of lumps of wood. The focus is a little soft on his hands and knees', '2006-10-14 03:46:33.000000', NULL, 1),
(2927691, 409657, 48545, '<td valign="top">lovely image, lighting, focus.  Some might be looking for the ''amusing factor'' however I like its simplicity and elegance.  minor issue is the front of the face is a little ''hot''.</td>', 'lovely image, lighting, focus.  Some might be looking for the ''amusing factor'' however I like its simplicity and elegance.  minor issue is the front of the face is a little ''hot''.', '2006-10-14 03:46:39.000000', NULL, 1),
(2927692, 409282, 48545, '<td valign="top">Nice image, made me smile, when I first read the sign thought it was moody not woody!</td>', 'Nice image, made me smile, when I first read the sign thought it was moody not woody!', '2006-10-14 03:46:44.000000', NULL, 1),
(2927693, 409397, 48545, '<td valign="top">Nice angle, not sure if the border adds to the image at all.  Best of the outdoor Woody photos.  Fun title</td>', 'Nice angle, not sure if the border adds to the image at all.  Best of the outdoor Woody photos.  Fun title', '2006-10-14 03:46:48.000000', NULL, 1),
(2927694, 408617, 48545, '<td valign="top">perfect lighting, composition etc. It raised an interesting question for me, that it just didn''t ''rock my boat'' as much as a couple of others photos have. 7</td>', 'perfect lighting, composition etc. It raised an interesting question for me, that it just didn''t ''rock my boat'' as much as a couple of others photos have. 7', '2006-10-14 03:46:53.000000', NULL, 1),
(2927695, 409761, 48545, '<td valign="top">very interesting photo, fun and plenty to look at.  For me the ladder (object at the front left) was a little too distracting), I love the front chair and the pot that are out of focus.</td>', 'very interesting photo, fun and plenty to look at.  For me the ladder (object at the front left) was a little too distracting), I love the front chair and the pot that are out of focus.', '2006-10-14 03:46:59.000000', NULL, 1),
(2927696, 409661, 48545, '<td valign="top">nice image, simple with feeling, lighting a little harsh (but doesn''t ruin the photo at all).  I don''t know if its just me looking at too many pictures of woodys however the image looks a little soft (again doesn''t ruin the photo at all)</td>', 'nice image, simple with feeling, lighting a little harsh (but doesn''t ruin the photo at all).  I don''t know if its just me looking at too many pictures of woodys however the image looks a little soft (again doesn''t ruin the photo at all)', '2006-10-14 03:47:05.000000', NULL, 1),
(2927697, 407901, 48545, '<td valign="top">My second favourite outdoor shot - really nice.  Nicely cloned out stand (or else you used some fishing wire around woodys neck!!), strange dark area around woody''s right arm.</td>', 'My second favourite outdoor shot - really nice.  Nicely cloned out stand (or else you used some fishing wire around woodys neck!!), strange dark area around woody''s right arm.', '2006-10-14 03:47:09.000000', NULL, 1),
(2927698, 409827, 48545, '<td valign="top">Great duotone, interesting colours.  The sharpness in the negative is great, just my opinion, I''d have liked to have seen this through out the image.  The photo doesn''t tell a story as cleanly as some of the photos, however taken on purely face value - I like it -6</td>', 'Great duotone, interesting colours.  The sharpness in the negative is great, just my opinion, I''d have liked to have seen this through out the image.  The photo doesn''t tell a story as cleanly as some of the photos, however taken on purely face value - I like it -6', '2006-10-14 03:47:14.000000', NULL, 1),
(2927699, 409703, 48545, '<td valign="top">Nice, the woodpecker almost looks fake.  My only problem was when I first looked at the image, the seeds merged with the bokeh background and made things a little confused, great shot though.</td>', 'Nice, the woodpecker almost looks fake.  My only problem was when I first looked at the image, the seeds merged with the bokeh background and made things a little confused, great shot though.', '2006-10-14 03:47:19.000000', NULL, 1),
(2927701, 409811, 48545, '<td valign="top">very cleverly done, I like an image that I can come back to and enjoy a second and third time</td>', 'very cleverly done, I like an image that I can come back to and enjoy a second and third time', '2006-10-14 03:47:25.000000', NULL, 1),
(2927702, 409177, 48545, '<td valign="top">really good technicals, and it put a smile on my face as well!</td>', 'really good technicals, and it put a smile on my face as well!', '2006-10-14 03:47:29.000000', NULL, 1),
(2927703, 409285, 48545, '<td valign="top">nice, not sure if the de-sat is necessary, great focus and pose</td>', 'nice, not sure if the de-sat is necessary, great focus and pose', '2006-10-14 03:47:34.000000', NULL, 1),
(2927704, 409482, 48545, '<td valign="top">Like the stocky woody, like the idea that he has  been whittled down from the block of wood.  It would have worked better if the the peg was bigger than the woody.  Lighting good, image is a little soft over all.  Nice work!</td>', 'Like the stocky woody, like the idea that he has  been whittled down from the block of wood.  It would have worked better if the the peg was bigger than the woody.  Lighting good, image is a little soft over all.  Nice work!', '2006-10-14 03:47:38.000000', NULL, 1),
(2927705, 407528, 48545, '<td valign="top">nice angle, adds a nice ''personal'' feel to the photo.  For me the out of focus hands detract from the photo, not add to it</td>', 'nice angle, adds a nice ''personal'' feel to the photo.  For me the out of focus hands detract from the photo, not add to it', '2006-10-14 03:47:42.000000', NULL, 1),
(2927706, 409582, 48545, '<td valign="top">great outdoor woody photo.  The photo is quite busy which will probably affect peoples score.  I like its sharpness and angle!</td>', 'great outdoor woody photo.  The photo is quite busy which will probably affect peoples score.  I like its sharpness and angle!', '2006-10-14 03:47:46.000000', NULL, 1),
(2927707, 406150, 48545, '<td valign="top">a lot going on.  The focus is so shallow that it doesn''t keep the viewer in the photo for long.  You almost have to struggle with the photo to work out what is going on. (I suppose this could be a good or bad thing).  Not sure what that big blob in the top left is either!</td>', 'a lot going on.  The focus is so shallow that it doesn''t keep the viewer in the photo for long.  You almost have to struggle with the photo to work out what is going on. (I suppose this could be a good or bad thing).  Not sure what that big blob in the top left is either!', '2006-10-14 03:47:52.000000', NULL, 1),
(2927708, 408362, 48545, '<td valign="top">Nicely put together, couple of strange shadows cast on the sheet behind.  Also, the creases in the sheet always seem to give the illusion of a less than professional shot.  Personally I love it, I''m guessing fishing line to hang the items up.  Good photo!!</td>', 'Nicely put together, couple of strange shadows cast on the sheet behind.  Also, the creases in the sheet always seem to give the illusion of a less than professional shot.  Personally I love it, I''m guessing fishing line to hang the items up.  Good photo!!', '2006-10-14 03:47:57.000000', NULL, 1),
(2927709, 409797, 48545, '<td valign="top">I really wish the wires had been cloned out.  Great idea and good execution.  Allows the viewer to make a story for the image and title! good stuff</td>', 'I really wish the wires had been cloned out.  Great idea and good execution.  Allows the viewer to make a story for the image and title! good stuff', '2006-10-14 03:48:02.000000', NULL, 1),
(2927710, 409442, 48545, '<td valign="top">Nice photo, atmospheric, wish the woody was free from its stand by balancing or hanging with fishing line etc.   Good image and lighting</td>', 'Nice photo, atmospheric, wish the woody was free from its stand by balancing or hanging with fishing line etc.   Good image and lighting', '2006-10-14 03:48:07.000000', NULL, 1),
(2927711, 407311, 48545, '<td valign="top">Is this the only close up of a woody? nice picture and great angle, providing atmosphere and entertainment!</td>', 'Is this the only close up of a woody? nice picture and great angle, providing atmosphere and entertainment!', '2006-10-14 03:48:11.000000', NULL, 1),
(2927712, 409738, 48545, '<td valign="top">Good conversion, nice lighting, made me smile</td>', 'Good conversion, nice lighting, made me smile', '2006-10-14 03:48:15.000000', NULL, 1),
(2927866, 408833, 35602, '<td valign="top">Very nice lighting.</td>', 'Very nice lighting.', '2006-10-14 08:06:39.000000', NULL, 1),
(2927868, 409703, 35602, '<td valign="top">What a great setup.  Birds are just so curious.  It looks like the woody is giving a dissertation on the merits of bird seed.</td>', 'What a great setup.  Birds are just so curious.  It looks like the woody is giving a dissertation on the merits of bird seed.', '2006-10-14 08:07:52.000000', NULL, 1),
(2927871, 408823, 35602, '<td valign="top">Very neat affects.  Love the lighting on the woody, and the stars in the background really put this one over the top.</td>', 'Very neat affects.  Love the lighting on the woody, and the stars in the background really put this one over the top.', '2006-10-14 08:09:23.000000', NULL, 1),
(2927873, 409826, 35602, '<td valign="top">Very nice paradox on this one.  Like the approach.</td>', 'Very nice paradox on this one.  Like the approach.', '2006-10-14 08:11:39.000000', NULL, 1),
(2927878, 409570, 35602, '<td valign="top">Oh wow.  I don''t like daddy long legs.  They scare me.  The idea is really good, though.  I think that the focus may have been too soft, though.  Composition is well done.</td>', 'Oh wow.  I don''t like daddy long legs.  They scare me.  The idea is really good, though.  I think that the focus may have been too soft, though.  Composition is well done.', '2006-10-14 08:13:50.000000', NULL, 1),
(2927880, 409572, 35602, '<td valign="top">Very sharp shadow on this one.  Overall, the image may be too overblown in the highlights of the foreground.  Your shadow, though, is extremely carved and grabs the eye most.</td>', 'Very sharp shadow on this one.  Overall, the image may be too overblown in the highlights of the foreground.  Your shadow, though, is extremely carved and grabs the eye most.', '2006-10-14 08:15:39.000000', NULL, 1),
(2927883, 408617, 35602, '<td valign="top">I didn''t think you could create emotion from a woody, but you did a fine job in this image.  The lighting adds to the emotion of despair.  Composition is really the best I''ve seen so far on the woody''s.</td>', 'I didn''t think you could create emotion from a woody, but you did a fine job in this image.  The lighting adds to the emotion of despair.  Composition is really the best I''ve seen so far on the woody''s.', '2006-10-14 08:17:44.000000', NULL, 1),
(2927913, 409379, 16241, '<td valign="top">i think you didnt understand the challenge, as you probably realised by now.<br/>sorry</td>', 'i think you didnt understand the challenge, as you probably realised by now.sorry', '2006-10-14 08:49:34.000000', NULL, 1),
(2928167, 408764, 65964, '<td valign="top">Like this one ! Good humor!</td>', 'Like this one ! Good humor!', '2006-10-14 11:43:00.000000', NULL, 1),
(2928169, 408254, 65964, '<td valign="top">To small sorry.</td>', 'To small sorry.', '2006-10-14 11:44:19.000000', NULL, 1),
(2928175, 409593, 65964, '<td valign="top">Like this one. Colors sharpness the background !</td>', 'Like this one. Colors sharpness the background !', '2006-10-14 11:51:11.000000', NULL, 1),
(2928195, 409826, 66201, '<td valign="top">Natty idea: what fun. Find the spacing a bit "bitty"...too many primary characters...maybe a repositioning of the artist''s page would make more of Woody adn his subject? At present the page is too dominant. But the stroy behind the composition is clever!</td>', 'Natty idea: what fun. Find the spacing a bit "bitty"...too many primary characters...maybe a repositioning of the artist''s page would make more of Woody adn his subject? At present the page is too dominant. But the stroy behind the composition is clever!', '2006-10-14 12:13:01.000000', NULL, 1),
(2928199, 408617, 66201, '<td valign="top">I like the balance of low horizontal figure and a large 3/4 background. Just something about the light on Woody makes him just too grey, and although it''s a shot of "despair" maybe his highlights could have been picked up more. I can imagine that with some tweeks, this could make a great enlargement poster!</td>', 'I like the balance of low horizontal figure and a large 3/4 background. Just something about the light on Woody makes him just too grey, and although it''s a shot of "despair" maybe his highlights could have been picked up more. I can imagine that with some tweeks, this could make a great enlargement poster!', '2006-10-14 12:13:54.000000', NULL, 1),
(2928312, 409397, 54172, '<td valign="top">I think the frame doesn''t go here too well. The image is just too dark.</td>', 'I think the frame doesn''t go here too well. The image is just too dark.', '2006-10-14 13:31:17.000000', NULL, 1),
(2928315, 409515, 54172, '<td valign="top">Wonderful idea!</td>', 'Wonderful idea!', '2006-10-14 13:32:36.000000', NULL, 1),
(2928322, 409719, 54172, '<td valign="top">Very cool idea. I think the white balance is a little off and lighting could be improved.</td>', 'Very cool idea. I think the white balance is a little off and lighting could be improved.', '2006-10-14 13:34:50.000000', NULL, 1),
(2928325, 409811, 54172, '<td valign="top">Enter your comment here, and then cast yourjavascript: do_vote(4)<br/> 4  vote...</td>', 'Enter your comment here, and then cast yourjavascript: do_vote(4) 4  vote...', '2006-10-14 13:36:29.000000', NULL, 1),
(2928340, 406761, 62187, '<td valign="top">That''s great! Got your idea from the 3rd place (I''m pretty sure) silhouette winner? Edges are a little jagged...good luck to ya!</td>', 'That''s great! Got your idea from the 3rd place (I''m pretty sure) silhouette winner? Edges are a little jagged...good luck to ya!', '2006-10-14 13:45:33.000000', NULL, 1),
(2928343, 409812, 62187, '<td valign="top">Too funny...your brave...good luck to ya.</td>', 'Too funny...your brave...good luck to ya.', '2006-10-14 13:46:17.000000', NULL, 1),
(2928459, 406453, 44490, '<td valign="top">Nice idea, red color, lighting, good execution - pun intended only as it is redeemed by grace being poured out.  I''m wondering about different composition and perspective, but the image is still simple, powerful, and effective.  Well done, my good and faithful servant.</td>', 'Nice idea, red color, lighting, good execution - pun intended only as it is redeemed by grace being poured out.  I''m wondering about different composition and perspective, but the image is still simple, powerful, and effective.  Well done, my good and faithful servant.', '2006-10-14 15:22:23.000000', NULL, 1),
(2928507, 409410, 54778, '<td valign="top">very lovely setting and persepective.. what have you been doing to the poor guy.. hmm..</td>', 'very lovely setting and persepective.. what have you been doing to the poor guy.. hmm..', '2006-10-14 15:59:47.000000', NULL, 1),
(2928550, 407358, 57229, '<td valign="top">It''s a wooden floor, but the term ''woody'' and its use here is in the challenge description. 1</td>', 'It''s a wooden floor, but the term ''woody'' and its use here is in the challenge description. 1', '2006-10-14 16:31:38.000000', NULL, 1),
